const CATS: Record<Category, { label: string; icon: string; color: string; blurb: string }> = {
  phishing:  { label: 'Phishing',     icon: 'ti-mail-opened',      color: '#CFFAFE', blurb: 'Fraudulent emails designed to steal credentials or money' },
  vishing:   { label: 'Vishing',      icon: 'ti-phone-call',       color: '#E0F2FE', blurb: 'Voice calls that impersonate trusted people or services' },
  smishing:  { label: 'Smishing',     icon: 'ti-message',          color: '#ECFEFF', blurb: 'SMS and messaging scams with malicious links' },
  pretexting:{ label: 'Pretexting',   icon: 'ti-user-exclamation', color: '#F0F9FF', blurb: 'Fabricated stories used to extract sensitive information' },
  baiting:   { label: 'Baiting',      icon: 'ti-package',          color: '#F0FDFA', blurb: 'Physical or digital lures that tempt you into a trap' },
  physical:  { label: 'Physical SE',  icon: 'ti-door-enter',       color: '#FEF3C7', blurb: 'In-person social engineering: tailgating, dumpster diving, shoulder surfing' },
  deepfake:  { label: 'AI / Deepfake',icon: 'ti-robot',            color: '#FCE7F3', blurb: 'AI-generated voice and video used for fraud' },
};
const DIFF_COLORS = { easy: 'var(--color-text-success)', medium: 'var(--color-text-warning)', hard: 'var(--color-text-danger)' };
const CAT_ORDER: Category[] = ['phishing', 'vishing', 'smishing', 'pretexting', 'baiting', 'physical', 'deepfake'];

interface Props { completedResults: Record<number, boolean>; onResult: (id: number, passed: boolean) => void; }

export default function SimulationsPage({ completedResults, onResult }: Props) {
  const [section, setSection] = useState<Category | null>(null);
  const [selected, setSelected] = useState<Scenario | null>(null);
  const [chosen, setChosen] = useState<number | null>(null);
  const [submitting, setSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const s = (style: React.CSSProperties = {}) => ({ fontFamily: 'var(--font-sans)', ...style });
  const card = { background: 'var(--color-background-primary)', border: '0.5px solid var(--color-border-tertiary)', borderRadius: 'var(--border-radius-lg)', padding: '16px 18px' };

  const totalDone = Object.keys(completedResults).length;
  const totalPassed = Object.values(completedResults).filter(Boolean).length;

  const sectionStats = (cat: Category) => {
    const items = SCENARIOS.filter(sc => sc.cat === cat);
    const done = items.filter(sc => completedResults[sc.id] !== undefined).length;
    const passed = items.filter(sc => completedResults[sc.id] === true).length;
    return { total: items.length, done, passed };
  };

  const openScenario = (sc: Scenario) => { setSelected(sc); setChosen(null); setSubmitted(false); };

  const handleAnswer = async (sc: Scenario, optIdx: number) => {
    if (chosen !== null) return;
    setChosen(optIdx);
    const passed = sc.choices[optIdx].correct;
    setSubmitting(true);
    try {
      const res = await simApi.submit({ scenarioId: sc.id, category: sc.cat, difficulty: sc.diff, passed, chosen: optIdx });
      onResult(sc.id, passed);
      if (res.newBadges.length > 0) res.newBadges.forEach((b: { label: string }) => showToast(`Badge unlocked: ${b.label}`, 'badge'));
      if (passed && res.xpEarned > 0) showToast(`Correct! +${res.xpEarned} XP`, 'success', res.xpEarned);
      else if (passed) showToast('Correct — already completed (no extra XP)', 'success');
      else showToast('Incorrect — read the feedback below. No XP awarded.', 'error');
    } catch (e) {
      showToast((e as Error).message, 'error');
    } finally {
      setSubmitting(false);
      setSubmitted(true);
    }
  };

  const renderScene = (sc: Scenario) => {
    const { scene } = sc;
    if (scene.type === 'email') return (
      <div style={{ border: '0.5px solid var(--color-border-tertiary)', borderRadius: 'var(--border-radius-md)', overflow: 'hidden', marginBottom: 14 }}>
        <div style={{ background: 'var(--color-background-secondary)', padding: '8px 14px', fontSize: 11, color: 'var(--color-text-secondary)', borderBottom: '0.5px solid var(--color-border-tertiary)' }}>
          Email inbox
        </div>
        <div style={{ padding: 14 }}>
          <div style={{ fontSize: 12, marginBottom: 4 }}><span style={{ color: 'var(--color-text-secondary)', minWidth: 36, display: 'inline-block' }}>From:</span><span style={{ color: 'var(--color-text-danger)' }}>{scene.from}</span></div>
          <div style={{ fontSize: 12, marginBottom: 4, color: 'var(--cs-text)' }}><span style={{ color: 'var(--color-text-secondary)', minWidth: 36, display: 'inline-block' }}>To:</span>{scene.to}</div>
          <div style={{ fontSize: 14, fontWeight: 500, margin: '10px 0 8px', color: 'var(--cs-text)' }}>{scene.subject}</div>
          <div style={{ fontSize: 13, lineHeight: 1.7, whiteSpace: 'pre-wrap', color: 'var(--cs-text)' }}>{scene.body}</div>
        </div>
      </div>
    );
    if (scene.type === 'sms') return (
      <div style={{ background: 'var(--color-background-secondary)', borderRadius: 'var(--border-radius-lg)', padding: 14, marginBottom: 14, maxWidth: 340 }}>
        <div style={{ fontSize: 11, color: 'var(--color-text-secondary)', marginBottom: 8 }}>From: {scene.from}</div>
        <div style={{ background: 'var(--color-background-primary)', borderRadius: '12px 12px 12px 3px', padding: '10px 14px', fontSize: 13, lineHeight: 1.6, border: '0.5px solid var(--color-border-tertiary)' }}>{scene.body}</div>
      </div>
    );
    if (scene.type === 'call') return (
      <div style={{ display: 'flex', gap: 12, background: 'var(--color-background-secondary)', borderRadius: 'var(--border-radius-lg)', padding: '14px 16px', marginBottom: 14 }}>
        <div style={{ width: 40, height: 40, borderRadius: '50%', background: 'var(--color-background-warning)', display: 'flex', alignItems: 'center', justifyContent: 'center', fontSize: 18, flexShrink: 0 }}>📞</div>
        <div style={{ fontSize: 13, lineHeight: 1.7 }}>
          <div style={{ fontSize: 11, fontWeight: 500, color: 'var(--color-text-secondary)', marginBottom: 6 }}>{scene.caller}</div>
          <div>{scene.transcript}</div>
        </div>
      </div>
    );
    if (scene.type === 'chat') return (
      <div style={{ background: 'var(--color-background-secondary)', borderRadius: 'var(--border-radius-lg)', padding: 14, marginBottom: 14 }}>
        <div style={{ fontSize: 11, fontWeight: 500, color: 'var(--color-text-secondary)', marginBottom: 10 }}>{scene.platform}</div>
        {scene.messages?.map((m, i) => (
          <div key={i} style={{ marginBottom: 10 }}>
            <div style={{ fontSize: 11, fontWeight: 500, color: 'var(--color-text-secondary)', marginBottom: 3 }}>{m.s}</div>
            <div style={{ background: 'var(--color-background-primary)', borderRadius: 8, padding: '8px 12px', fontSize: 13, lineHeight: 1.6, border: '0.5px solid var(--color-border-tertiary)', display: 'inline-block', maxWidth: '90%' }}>{m.m}</div>
          </div>
        ))}
      </div>
    );
    return null;
  };

  // ── Scenario play view ──────────────────────────────────────────
  if (selected) {
    const cat = CATS[selected.cat];
    const sectionScenarios = SCENARIOS.filter(sc => sc.cat === selected.cat);
    const idxInSection = sectionScenarios.findIndex(sc => sc.id === selected.id);
    return (
      <div style={s({ maxWidth: 600 })}>
        <button onClick={() => setSelected(null)} style={s({ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--color-text-secondary)', fontSize: 12, marginBottom: 14, display: 'flex', alignItems: 'center', gap: 4 })}>
          <i className="ti ti-arrow-left" /> Back to {cat.label} section
        </button>
        <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 16 }}>
          <div style={{ width: 40, height: 40, borderRadius: 'var(--border-radius-md)', background: 'var(--cs-primary-soft)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--cs-primary)', flexShrink: 0 }}>
            <i className={`ti ${cat.icon}`} style={{ fontSize: 18 }} />
          </div>
          <div>
            <div style={{ fontSize: 16, fontWeight: 500 }}>{selected.title}</div>
            <div style={{ fontSize: 12, color: 'var(--color-text-secondary)' }}>{cat.label} · <span style={{ color: DIFF_COLORS[selected.diff], fontWeight: 500 }}>{selected.diff}</span></div>
          </div>
        </div>
        {renderScene(selected)}
        <div style={{ fontSize: 13, fontWeight: 500, marginBottom: 8, color: 'var(--color-text-secondary)' }}>What do you do?</div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 8, marginBottom: 14 }}>
          {selected.choices.map((c, i) => {
            let bg = 'var(--color-background-primary)', border = 'var(--color-border-secondary)', color = 'var(--color-text-primary)';
            if (chosen !== null) {
              if (i === selected.choices.findIndex(x => x.correct)) { bg = 'var(--color-background-success)'; border = 'var(--color-border-success)'; color = 'var(--color-text-success)'; }
              else if (i === chosen && !selected.choices[chosen].correct) { bg = 'var(--color-background-danger)'; border = 'var(--color-border-danger)'; color = 'var(--color-text-danger)'; }
            }
            return (
              <button key={i} onClick={() => handleAnswer(selected, i)} disabled={chosen !== null || submitting}
                style={s({ width: '100%', textAlign: 'left', padding: '12px 14px', fontSize: 13, cursor: chosen !== null ? 'default' : 'pointer', background: bg, border: `0.5px solid ${border}`, borderRadius: 'var(--border-radius-md)', color, pointerEvents: chosen !== null ? 'none' : 'auto' })}>
                <span style={{ fontWeight: 500, marginRight: 8, opacity: 0.6 }}>{String.fromCharCode(65 + i)}.</span>{c.text}
              </button>
            );
          })}
        </div>
        {chosen !== null && (
          <div style={{ padding: '14px 16px', borderRadius: 'var(--border-radius-md)', fontSize: 13, lineHeight: 1.6, background: selected.choices[chosen].correct ? 'var(--color-background-success)' : 'var(--color-background-danger)', color: selected.choices[chosen].correct ? 'var(--color-text-success)' : 'var(--color-text-danger)', border: `0.5px solid ${selected.choices[chosen].correct ? 'var(--color-border-success)' : 'var(--color-border-danger)'}`, marginBottom: 12 }}>
            <div style={{ fontWeight: 500, marginBottom: 4 }}>{selected.choices[chosen].correct ? '✓ Correct — well spotted' : '✗ Incorrect — here is what you missed'}</div>
            <div>{selected.choices[chosen].correct ? selected.feedback.pass : selected.feedback.fail}</div>
            <div style={{ marginTop: 10, display: 'flex', gap: 6, flexWrap: 'wrap' }}>
              <span style={{ fontSize: 11, opacity: 0.7 }}>Tactics used:</span>
              {selected.tactics.map(t => <span key={t} style={{ fontSize: 10, padding: '2px 8px', borderRadius: 20, background: 'rgba(0,0,0,0.1)', fontWeight: 500 }}>{t}</span>)}
            </div>
          </div>
        )}
        {submitted && (
          <div style={{ display: 'flex', gap: 8 }}>
            {idxInSection > 0 && <button onClick={() => openScenario(sectionScenarios[idxInSection - 1])} style={s({ padding: '8px 14px', fontSize: 12, cursor: 'pointer', background: 'var(--color-background-secondary)', border: 'none', borderRadius: 'var(--border-radius-md)' })}> ← Previous</button>}
            {idxInSection < sectionScenarios.length - 1 && <button onClick={() => openScenario(sectionScenarios[idxInSection + 1])} style={s({ padding: '8px 14px', fontSize: 12, fontWeight: 500, cursor: 'pointer', background: 'var(--color-brand)', color: '#fff', border: 'none', borderRadius: 'var(--border-radius-md)' })}> Next in section →</button>}
          </div>
        )}
      </div>
    );
  }

  // ── Section (single category) view ──────────────────────────────
  if (section) {
    const cat = CATS[section];
    const items = SCENARIOS.filter(sc => sc.cat === section);
    const st = sectionStats(section);
    return (
      <div style={s()}>
        <button onClick={() => setSection(null)} style={s({ background: 'none', border: 'none', cursor: 'pointer', color: 'var(--color-text-secondary)', fontSize: 12, marginBottom: 14, display: 'flex', alignItems: 'center', gap: 4 })}>
          <i className="ti ti-arrow-left" /> All sections
        </button>
        <div style={{ display: 'flex', alignItems: 'center', gap: 12, marginBottom: 6 }}>
          <div style={{ width: 44, height: 44, borderRadius: 'var(--border-radius-md)', background: 'var(--cs-primary-soft)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--cs-primary)' }}>
            <i className={`ti ${cat.icon}`} style={{ fontSize: 20 }} />
          </div>
          <div>
            <div style={{ fontSize: 17, fontWeight: 600 }}>{cat.label} Section</div>
            <div style={{ fontSize: 12, color: 'var(--color-text-secondary)' }}>{cat.blurb}</div>
          </div>
        </div>
        <div style={{ fontSize: 12, color: 'var(--color-text-secondary)', marginBottom: 14 }}>
          {st.done}/{st.total} attempted · {st.passed} passed
        </div>
        <div style={{ display: 'flex', flexDirection: 'column', gap: 7 }}>
          {items.map(sc => {
            const done = completedResults[sc.id] !== undefined;
            const passed = completedResults[sc.id];
            return (
              <div key={sc.id} onClick={() => openScenario(sc)}
                style={s({ display: 'flex', alignItems: 'center', gap: 12, padding: '11px 14px', background: 'var(--color-background-primary)', border: `0.5px solid ${done ? (passed ? 'var(--color-border-success)' : 'var(--color-border-danger)') : 'var(--color-border-tertiary)'}`, borderRadius: 'var(--border-radius-md)', cursor: 'pointer', borderLeft: done ? `3px solid ${passed ? 'var(--color-text-success)' : 'var(--color-text-danger)'}` : undefined, color: 'var(--cs-text)' })}>
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{ fontSize: 13, fontWeight: 600, overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap', color: 'var(--cs-text)' }}>{sc.title}</div>
                  <div style={{ fontSize: 11, color: 'var(--color-text-secondary)', marginTop: 1 }}>{sc.desc}</div>
                </div>
                <span style={{ fontSize: 11, fontWeight: 500, color: DIFF_COLORS[sc.diff], flexShrink: 0 }}>{sc.diff}</span>
                {done ? <span style={{ fontSize: 16 }}>{passed ? '✓' : '✗'}</span> : <i className="ti ti-chevron-right" style={{ fontSize: 14, color: 'var(--color-text-tertiary)' }} />}
              </div>
            );
          })}
        </div>
      </div>
    );
  }

  // ── Sections hub ────────────────────────────────────────────────
  return (
    <div style={s()}>
      <div style={{ fontSize: 18, fontWeight: 700, marginBottom: 4, color: 'var(--cs-text)' }}>Simulation Centre</div>
      <div style={{ fontSize: 12, color: 'var(--color-text-secondary)', marginBottom: 6 }}>
        Interactive attack scenarios organised by threat type. Choose a section to practise.
      </div>
      <div style={{ fontSize: 11, color: 'var(--color-text-tertiary)', marginBottom: 16 }}>
        Unlike the Quiz (knowledge questions), simulations put you inside a realistic email, call, SMS, or chat and ask what you would do.
      </div>

      <div className="cs-grid-4" style={{ marginBottom: 18 }}>
        {[
          { label: 'Completed', value: `${totalDone}/175`, color: 'var(--color-text-info)' },
          { label: 'Passed', value: totalPassed, color: 'var(--color-text-success)' },
          { label: 'Failed', value: totalDone - totalPassed, color: 'var(--color-text-danger)' },
          { label: 'Pass rate', value: totalDone > 0 ? `${Math.round((totalPassed / totalDone) * 100)}%` : '—', color: 'var(--color-text-warning)' },
        ].map(st => (
          <div key={st.label} style={{ background: 'var(--color-background-secondary)', borderRadius: 'var(--border-radius-md)', padding: '10px 12px' }}>
            <div style={{ fontSize: 11, color: 'var(--color-text-secondary)' }}>{st.label}</div>
            <div style={{ fontSize: 20, fontWeight: 500, color: st.color, marginTop: 2 }}>{st.value}</div>
          </div>
        ))}
      </div>

      <div style={{ fontSize: 14, fontWeight: 600, marginBottom: 12, color: 'var(--cs-text)' }}>Choose a section</div>
      <div className="cs-grid-2">
        {CAT_ORDER.map(key => {
          const cat = CATS[key];
          const st = sectionStats(key);
          const pct = st.total > 0 ? Math.round((st.done / st.total) * 100) : 0;
          return (
            <button key={key} onClick={() => setSection(key)}
              style={s({ textAlign: 'left', cursor: 'pointer', background: 'var(--color-background-primary)', border: '0.5px solid var(--color-border-tertiary)', borderRadius: 'var(--border-radius-lg)', padding: '14px 16px', display: 'flex', gap: 12, alignItems: 'flex-start', color: 'var(--cs-text)' })}>
              <div style={{ width: 40, height: 40, borderRadius: 'var(--border-radius-md)', background: 'var(--cs-primary-soft)', display: 'flex', alignItems: 'center', justifyContent: 'center', color: 'var(--cs-primary)', flexShrink: 0 }}>
                <i className={`ti ${cat.icon}`} style={{ fontSize: 18 }} />
              </div>
              <div style={{ flex: 1, minWidth: 0 }}>
                <div style={{ fontSize: 15, fontWeight: 700, marginBottom: 3, color: 'var(--cs-text)', letterSpacing: '-0.01em' }}>{cat.label}</div>
                <div style={{ fontSize: 11, color: 'var(--color-text-secondary)', marginBottom: 8, lineHeight: 1.4 }}>{cat.blurb}</div>
                <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
                  <div style={{ flex: 1, height: 5, background: 'var(--color-border-tertiary)', borderRadius: 3, overflow: 'hidden' }}>
                    <div style={{ height: '100%', width: `${pct}%`, background: 'var(--color-brand)', borderRadius: 3 }} />
                  </div>
                  <span style={{ fontSize: 12, fontWeight: 600, color: 'var(--cs-text)', flexShrink: 0 }}>{st.done}/{st.total}</span>
                </div>
              </div>
            </button>
          );
        })}
      </div>
    </div>
  );
}
